434	      "type": "choice",
435	      "choice": "returns",
436	      "confidence": 0.42,
437	      "probabilities": {
438	        "shipping": 0.04,
439	        "billing": 0.35,
440	        "returns": 0.61
441	      }
442	    },
443	    "return_reason": {
444	      "type": "choice",
445	      "choice": "wrong_size",
446	      "confidence": 1.0,
447	      "probabilities": {
448	        "other": 0.0,
449	        "wrong_size": 1.0,
450	        "changed_mind": 0.0,
451	        "damaged": 0.0,
452	        "wrong_item": 0.0
453	      }
454	    },
455	    "shipping_issue": {
456	      "type": "choice",
457	      "choice": "delayed",
458	      "confidence": 0.67,
459	      "probabilities": {
460	        "wrong_address": 0.0,
461	        "other": 0.26,
462	        "not_delivered": 0.0,
463	        "damaged_in_transit": 0.0,
464	        "delayed": 0.74
465	      }
466	    },
467	    "requested_resolution": {
468	      "type": "choice",
469	      "choice": "refund",
470	      "confidence": 0.2,
471	      "probabilities": {
472	        "replacement": 0.34,
473	        "refund": 0.4,
474	        "information": 0.02,
475	        "exchange": 0.24
476	      }
477	    },
478	    "tone": {
479	      "type": "choice",
480	      "choice": "frustrated",
