83	export async function classifyGenre(
84	  moviePlot: string,
85	): Promise<{ genre: Genre; usage: { promptTokens: number; completionTokens: number; totalTokens: number }; model: string } | null> {
86	  const apiKey = process.env.OPENROUTER_API_KEY;
87	  if (!apiKey) {
88	    logJev('[jev] path=original reason=OPENROUTER_API_KEY not set');
89	    return null;
90	  }
91	
92	  const controller = new AbortController();
93	  const timeout = setTimeout(() => controller.abort(), JEV_TIMEOUT_MS);
94	
95	  try {
96	    const response = await fetch(JEV_BASE_URL, {
97	      method: 'POST',
98	      headers: {
99	        'Authorization': `Bearer ${apiKey}`,
100	        'Content-Type': 'application/json',
101	      },
102	      body: JSON.stringify({
103	        model: JEV_MODEL,
104	        state: moviePlot,
105	        questions: GENRE_QUESTION,
106	      }),
107	      signal: controller.signal,
108	    });
109	
110	    if (response.status === 429 || response.status >= 500) {
111	      logJev(`[jev] path=original reason=HTTP ${response.status}`);
112	      return null;
113	    }
114	
115	    if (!response.ok) {
116	      logJev(`[jev] path=original reason=HTTP ${response.status}`);
117	      return null;
118	    }
119	
120	    const body: JevResponse = await response.json();
121	
122	    const answer = body.answers?.genre;
123	    if (!answer || answer.type !== 'choice') {
124	      logJev('[jev] path=original reason=malformed response');
125	      return null;
126	    }
127	
128	    if (!isKnownGenre(answer.choice)) {
129	      logJev(`[jev] path=original reason=unknown genre label "${answer.choice}"`);
130	      return null;
131	    }
132	
133	    if (!isConfident(answer)) {
134	      logJev(`[jev] path=original reason=low confidence ${answer.confidence}`);
135	      return null;
136	    }
137	
138	    const adapted = adaptUsage(body.usage);
139	    if (!adapted) {
140	      logJev('[jev] path=original reason=invalid usage data');
141	      return null;
142	    }
143	
144	    logJev(`[jev] path=jev model=${body.model} genre=${answer.choice} confidence=${answer.confidence}`);
145	    return { genre: answer.choice, usage: adapted, model: body.model };
146	  } catch (err: unknown) {
147	    const msg = err instanceof Error ? err.message : String(err);
148	    logJev(`[jev] path=original reason=error: ${msg}`);
149	    return null;
150	  } finally {
151	    clearTimeout(timeout);
152	  }
